, "critical": "Severe agitation with paranoia or hallucinations, or cannabinoid hyperemesis with dehydration, hypokalemia, and acute kidney injury requiring IV fluids"}, "red_flags": [{"finding": "Severe agitation with paranoia or hallucinations", "meaning": "Acute psychosis; needs close observation and may require antipsychotic treatment"}, {"finding": "Persistent vomiting with inability to keep fluids down", "meaning": "Dehydration and electrolyte loss; needs IV fluids and electrolyte replacement"}, {"finding": "Hypotension or heart rate over 120", "meaning": "Volume depletion or another acute process; needs urgent evaluation"}, {"finding": "Focal weakness, numbness, or new seizure", "meaning": "Not explained by cannabis; evaluate for a structural or vascular cause"}, {"finding": "Chest pain or syncope after use", "meaning": "Possible cardiac complication; needs ECG and further workup"}, {"finding": "Suicidal ideation", "meaning": "Immediate safety risk; needs psychiatric evaluation"}], "complications": [{"name": "Cannabinoid hyperemesis syndrome", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["Years of daily use", "Recurrent vomiting", "Compulsive hot showers that relieve symptoms"]}, {"name": "Dehydration and acute kidney injury", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Persistent vomiting", "Elevated BUN and creatinine", "Low bicarbonate"]}, {"name": "Hypokalemia from vomiting", "timing": "any", "seriousness": "serious", "frequency": "sometimes", "clues": ["Repeated vomiting", "Muscle weakness", "Low serum potassium"]}, {"name": "Cannabis-induced psychosis", "timing": "any", "seriousness": "serious", "frequency": "rare", "clues": ["High-THC product use", "Paranoia or hallucinations", "Agitation"]}, {"name": "Cannabis use disorder", "timing": "late", "seriousness": "serious", "frequency": "common", "clues": ["Daily use", "Failed attempts to cut down", "Continued use despite problems"]}, {"