insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$chest-pain$rounds_kb$, $rounds_kb$Chest Pain$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$cardiovascular$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "chest-pain", "triage": {"name": "Chest Pain", "case_suitable": true, "reason": "Classic undifferentiated symptom with a broad, high-stakes differential (ACS, PE, dissection, GERD, musculoskeletal) reachable by history, exam, ECG and labs.", "kind": "symptom", "category": "undifferentiated cardiopulmonary symptom", "organ_systems": ["cardiovascular"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["emergency", "familyMedicine"], "commonness": "very_common", "settings": ["emergency", "clinic", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:30Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:53:18Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:53:25Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:53:48Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:54:00Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:54:09Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'ecg' to 'ECG'", "auto-repaired: workup: 'hs_tnt' was in ['initial', 'confirmatory'], kept ['initial']", "auto-repaired: workup: 'ct angiography of the chest with iv contrast' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'coronary angiography' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'd_dimer' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'lipase' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'ct angiography of the chest with iv contrast' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'coronary angiography' was in ['confirmatory', 'not_indicated'], kept ['not_indicated', 'confirmatory']", "auto-repaired: workup: 'd_dimer' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'lipase' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential acute-coronary-syndrome: no profile yet", "differential pulmonary-embolism: no profile yet", "differential aortic-dissection: no profile yet", "differential pericarditis: no profile yet", "differential pneumothorax: no profile yet", "differential community-acquired-pneumonia: no profile yet", "differential gastroesophageal-reflux-disease: no profile yet", "differential costochondritis: no profile yet", "differential panic-attack: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 25, "typical_max": 85, "peak": "50–75", "possible_min": 12, "possible_max": 100}, "sex": "either", "demographics": ["Chest pain is one of the most common reasons for emergency department visits in the US", "The mix of causes shifts with age: younger patients more often have musculoskeletal, gastrointestinal, or anxiety-related causes, while older patients more often have coronary or other cardiopulmonary causes", "Men tend to present with chest pain from coronary causes at younger ages than women"], "risk_factors": [{"text": "Coronary artery disease or prior myocardial infarction", "strength": "strong"}, {"text": "Diabetes mellitus", "strength": "strong"}, {"text": "Hypertension", "strength": "strong"}, {"text": "Hyperlipidemia", "strength": "strong"}, {"text": "Current or recent tobacco smoking", "strength": "strong"}, {"text": "Family history of premature coronary artery disease", "strength": "moderate"}, {"text": "Recent immobilization, surgery, or long travel (venous thromboembolism risk)", "strength": "moderate"}, {"text": "Known gastroesophageal reflux disease", "strength": "moderate"}, {"text": "Recent heavy lifting or new strenuous exercise", "strength": "weak"}, {"text": "Recent viral illness with coughing", "strength": "weak"}], "comorbidities": ["Coronary artery disease", "Heart failure", "Atrial fibrillation", "Diabetes mellitus", "Chronic obstructive pulmonary disease", "Gastroesophageal reflux disease", "Anxiety or panic disorder", "Prior venous thromboembolism"], "family_history": ["Premature coronary artery disease in a first-degree relative", "Sudden cardiac death in a first-degree relative", "Venous thromboembolism in a first-degree relative"], "social_history": ["Tobacco use", "Alcohol use", "Cocaine or stimulant use", "Sedentary lifestyle", "Occupational or recreational heavy lifting"], "exposures": ["Recent long-distance travel", "Recent surgery or hospitalization", "Recent immobilization or cast", "Sick contacts with respiratory illness"], "risk_medications": ["estrogen-containing contraceptives", "hormone replacement therapy", "cocaine", "amphetamines", "triptans", "nonsteroidal anti-inflammatory drugs", "chemotherapy agents"]}, "presentation": {"chief_complaints": [{"text": "I have pain in my chest", "frequency": "almost_always"}, {"text": "It feels like pressure or tightness in the middle of my chest", "frequency": "common"}, {"text": "The pain gets worse when I breathe in or lie down", "frequency": "sometimes"}, {"text": "I feel like I can't catch my breath", "frequency": "sometimes"}], "hpi": {"onset": "Varies by cause: sudden and maximal at onset suggests a vascular or pulmonary event, while gradual onset over minutes to hours is more typical of coronary or gastrointestinal causes", "duration": "From minutes to weeks depending on cause; cardiac pain often lasts minutes to tens of minutes, while musculoskeletal and gastrointestinal pain can persist for days", "progression": "May be constant, intermittent, or crescendo; pain that is worsening or occurring at rest is concerning for an acute coronary syndrome", "location": "Often substernal or left-sided, but can be anywhere in the chest, epigastrium, back, or shoulders", "radiation": "May radiate to the left arm, both arms, jaw, neck, back, or epigastrium", "quality": "Described as pressure, tightness, squeezing, heaviness, burning, sharp, or tearing depending on the cause", "severity": "Ranges from mild discomfort to severe; severity alone does not distinguish dangerous from benign causes", "timing": "May be exertional, postprandial, positional, pleuritic, or constant", "aggravating": ["Exertion", "Emotional stress", "Deep breathing", "Coughing", "Lying flat", "Pressing on the chest wall", "Eating a large meal"], "relieving": ["Rest", "Nitroglycerin", "Sitting upright or leaning forward", "Antacids", "Analgesics"], "associated_symptoms": [{"text": "Shortness of breath", "frequency": "common"}, {"text": "Sweating", "frequency": "sometimes"}, {"text": "Nausea or vomiting", "frequency": "sometimes"}, {"text": "Lightheadedness or dizziness", "frequency": "sometimes"}, {"text": "Palpitations", "frequency": "sometimes"}, {"text": "Heartburn or sour taste in the mouth", "frequency": "sometimes"}, {"text": "Cough", "frequency": "sometimes"}, {"text": "Pain worsened by movement or breathing", "frequency": "sometimes"}, {"text": "Fever", "frequency": "rare"}, {"text": "Coughing up blood", "frequency": "rare"}, {"text": "Fainting", "frequency": "rare"}], "pertinent_negatives": ["Tearing pain radiating to the back", "Pain that is maximal at the very first instant", "Coughing up blood", "Unilateral leg swelling or calf pain", "Recent long travel or immobilization", "Fever with productive cough", "Pain reproduced only by pressing on the chest wall", "Symptoms that resolve completely with antacids"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Feeling sweaty or clammy", "frequency": "sometimes"}, {"text": "Fatigue", "frequency": "sometimes"}, {"text": "Feeling feverish", "frequency": "rare"}], "negatives": ["Unintentional weight loss", "Night sweats"]}, {"system": "cardiovascular", "positives": [{"text": "Palpitations", "frequency": "sometimes"}, {"text": "Pain brought on by exertion", "frequency": "sometimes"}, {"text": "Leg swelling", "frequency": "rare"}], "negatives": ["Fainting", "Known heart murmur", "Prior heart attack"], "argues_against": ["Pain that is purely positional and reproducible on chest wall palpation"]}, {"system": "respiratory", "positives": [{"text": "Shortness of breath", "frequency": "common"}, {"text": "Cough", "frequency": "sometimes"}, {"text": "Pain worse with deep breath", "frequency": "sometimes"}], "negatives": ["Coughing up blood", "Wheezing", "Recent pneumonia"], "argues_against": ["Pleuritic pain with clear lungs and no dyspnea"]}, {"system": "gastrointestinal", "positives": [{"text": "Heartburn or acid regurgitation", "frequency": "sometimes"}, {"text": "Nausea", "frequency": "sometimes"}, {"text": "Pain after meals or when lying down", "frequency": "sometimes"}], "negatives": ["Vomiting blood", "Black or bloody stools", "Difficulty swallowing"], "argues_against": ["Pain clearly related to meals and relieved by antacids"]}, {"system": "musculoskeletal", "positives": [{"text": "Pain reproduced by pressing on the chest", "frequency": "sometimes"}, {"text": "Pain with twisting or reaching", "frequency": "sometimes"}], "negatives": ["Recent trauma", "Back pain", "Joint swelling"], "argues_against": ["Pain that is constant and not reproducible with movement or palpation"]}, {"system": "psychiatric", "positives": [{"text": "Feeling anxious or panicky", "frequency": "sometimes"}, {"text": "Racing thoughts", "frequency": "rare"}], "negatives": ["Suicidal ideation", "Recent major life stressor"]}]}, "exam": {"general": {"mild": "Comfortable, no distress, speaking in full sentences", "moderate": "Mild distress, diaphoretic, prefers to sit upright", "severe": "Marked distress, pale and diaphoretic, speaking in short sentences", "critical": "Toxic or moribund, altered mental status, unable to speak, may be hypotensive or unresponsive"}, "findings": [{"id": "chest-wall-reproducibility", "region": "musculoskeletal", "maneuver": "Palpate the anterior chest wall, including the sternum, costochondral junctions, and pectoral muscles", "finding": "Reproducible tenderness that recreates the patient's pain", "frequency": "common", "significance": "argues_against", "importance": "important"}, {"id": "normal-lung-exam", "region": "lung", "maneuver": "Auscultate all lung fields and percuss the chest", "finding": "Clear breath sounds without crackles, wheezes, or dullness", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-cardiac-exam", "region": "cardiac", "maneuver": "Auscultate the heart, palpate the precordium, and assess jugular venous pressure", "finding": "Regular rate and rhythm, no murmurs, rubs, or gallops, normal JVP", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-abdominal-exam", "region": "abdomen", "maneuver": "Palpate the abdomen and auscultate bowel sounds", "finding": "Soft, non-tender, no organomegaly or masses", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-extremities", "region": "extremities", "maneuver": "Inspect and palpate the lower extremities for edema, calf tenderness, and asymmetry", "finding": "No unilateral swelling, calf tenderness, or edema", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-skin", "region": "skin", "maneuver": "Inspect the skin for pallor, diaphoresis, rash, or ecchymoses", "finding": "Warm, dry, normal color, no rash", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-mental-status", "region": "mental_status", "maneuver": "Assess orientation, attention, and level of consciousness", "finding": "Alert and oriented, normal attention", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-neuro-exam", "region": "neuro", "maneuver": "Perform a focused neurologic exam including cranial nerves, strength, and sensation", "finding": "No focal deficits", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-heent", "region": "heent", "maneuver": "Inspect the oropharynx and neck for swelling or lymphadenopathy", "finding": "No swelling, erythema, or lymphadenopathy", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-neck", "region": "neck", "maneuver": "Palpate the neck for tracheal deviation, subcutaneous emphysema, and lymphadenopathy", "finding": "Trachea midline, no crepitus or masses", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-lymph", "region": "lymph", "maneuver": "Palpate cervical, supraclavicular, and axillary lymph nodes", "finding": "No lymphadenopathy", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-genitourinary", "region": "genitourinary", "maneuver": "Inspect and palpate the genitalia if indicated by history", "finding": "No abnormalities", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-rectal", "region": "rectal", "maneuver": "Perform a digital rectal exam if gastrointestinal bleeding is suspected", "finding": "No masses, normal tone, no blood", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-breast", "region": "breast", "maneuver": "Inspect and palpate the breasts if breast pathology is suspected", "finding": "No masses, skin changes, or nipple discharge", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "normal-pelvic", "region": "pelvic", "maneuver": "Perform a pelvic exam if a gynecologic cause is suspected", "finding": "No cervical motion tenderness, adnexal masses, or discharge", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}]}, "vitals": {"temp": {"mild": {"min": 98.6, "max": 99.5}, "moderate": {"min": 99.0, "max": 100.4}, "severe": {"min": 100.0, "max": 102.0}, "critical": {"min": 101.0, "max": 103.5}}, "hr": {"mild": {"min": 60, "max": 100}, "moderate": {"min": 80, "max": 110}, "severe": {"min": 100, "max": 130}, "critical": {"min": 120, "max": 160}}, "rr": {"mild": {"min": 12, "max": 20}, "moderate": {"min": 16, "max": 24}, "severe": {"min": 20, "max": 30}, "critical": {"min": 28, "max": 40}}, "sbp": {"mild": {"min": 100, "max": 140}, "moderate": {"min": 90, "max": 130}, "severe": {"min": 80, "max": 120}, "critical": {"min": 60, "max": 90}}, "dbp": {"mild": {"min": 60, "max": 90}, "moderate": {"min": 60, "max": 85}, "severe": {"min": 50, "max": 80}, "critical": {"min": 40, "max": 60}}, "spo2": {"mild": {"min": 95, "max": 100}, "moderate": {"min": 92, "max": 97}, "severe": {"min": 88, "max": 94}, "critical": {"min": 80, "max": 90}}}, "labs": [{"test_id": "hs_tnt", "ranges": {"mild": {"min": 15, "max": 30}, "moderate": {"min": 25, "max": 80}, "severe": {"min": 60, "max": 300}, "critical": {"min": 200, "max": 2000}}, "frequency": "sometimes", "importance": "essential", "caveat": "Normal or mildly elevated in non-cardiac chest pain; a rise or fall on serial sampling defines acute myocardial injury. Values are assay-dependent."}, {"test_id": "d_dimer", "ranges": {"mild": {"min": 0.6, "max": 1.5}, "moderate": {"min": 1.0, "max": 3.0}, "severe": {"min": 2.0, "max": 8.0}}, "frequency": "sometimes", "importance": "important", "caveat": "Normal in most non-PE chest pain; a negative result in a low-risk patient helps exclude pulmonary embolism. Nonspecific and rises with age, inflammation, pregnancy, and recent surgery."}, {"test_id": "bnp", "ranges": {"moderate": {"min": 150, "max": 500}, "severe": {"min": 400, "max": 1500}, "critical": {"min": 1000, "max": 5000}}, "frequency": "sometimes", "importance": "optional", "caveat": "Elevated when chest pain is from decompensated heart failure; normal in most other causes."}, {"test_id": "wbc", "ranges": {"mild": {"min": 11.5, "max": 14.0}, "moderate": {"min": 13.0, "max": 18.0}, "severe": {"min": 16.0, "max": 25.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Leukocytosis suggests pneumonia, pericarditis, or another inflammatory cause rather than ischemia."}, {"test_id": "crp", "ranges": {"mild": {"min": 1.5, "max": 5.0}, "moderate": {"min": 4.0, "max": 12.0}, "severe": {"min": 10.0, "max": 25.0}}, "frequency": "sometimes", "importance": "optional", "caveat": "Supports an inflammatory cause such as pericarditis; not useful for ruling in or out acute coronary syndrome."}, {"test_id": "lactate", "ranges": {"moderate": {"min": 2.2, "max": 4.0}, "severe": {"min": 3.5, "max": 8.0}}, "frequency": "rare", "importance": "optional", "caveat": "Elevated with shock, severe sepsis, or mesenteric ischemia; normal in most chest pain."}, {"test_id": "hcg", "frequency": "sometimes", "importance": "essential", "caveat": "Negative. Required in anyone who could be pregnant before imaging or medications that are contraindicated in pregnancy."}, {"test_id": "lipase", "ranges": {"moderate": {"min": 200, "max": 600}, "severe": {"min": 500, "max": 1500}}, "frequency": "rare", "importance": "optional", "caveat": "Ordered only when the pain is epigastric or radiates to the back and pancreatitis is a consideration."}, {"test_id": "ck", "ranges": {"moderate": {"min": 350, "max": 1000}, "severe": {"min": 800, "max": 5000}}, "frequency": "rare", "importance": "optional", "caveat": "Elevated with rhabdomyolysis or severe muscle injury; not a cardiac marker when troponin is available."}], "ecg": {"findings": [{"feature": "rhythm", "finding": "Sinus rhythm", "frequency": "almost_always"}, {"feature": "rate", "finding": "Tachycardia", "frequency": "sometimes"}, {"feature": "st", "finding": "ST-segment elevation in a coronary distribution with reciprocal depression", "frequency": "sometimes", "leads": ["II", "III", "aVF", "V1", "V2", "V3", "V4", "V5", "V6"], "min_severity": "severe"}, {"feature": "st", "finding": "ST-segment depression or dynamic T-wave inversion", "frequency": "sometimes", "leads": ["I", "II", "V4", "V5", "V6"], "min_severity": "moderate"}, {"feature": "t_wave", "finding": "Hyperacute peaked T waves early in infarction", "frequency": "rare", "min_severity": "moderate"}, {"feature": "st", "finding": "Diffuse PR-segment depression and diffuse concave ST elevation", "frequency": "sometimes", "min_severity": "moderate"}, {"feature": "other", "finding": "Electrical alternans with low-voltage QRS", "frequency": "rare", "min_severity": "severe"}, {"feature": "conduction", "finding": "New left bundle branch block", "frequency": "rare", "min_severity": "severe"}, {"feature": "rhythm", "finding": "Atrial fibrillation with rapid ventricular response", "frequency": "rare", "min_severity": "moderate"}, {"feature": "other", "finding": "Nonspecific ST-T changes", "frequency": "common"}]}, "imaging": [{"study": "Chest x-ray, posteroanterior and lateral", "modality": "xray", "findings": [{"text": "Clear lungs with no