insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$chronic-kidney-disease$rounds_kb$, $rounds_kb$Chronic Kidney Disease$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$renal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "chronic-kidney-disease", "triage": {"name": "Chronic Kidney Disease", "case_suitable": true, "reason": "Progressive kidney dysfunction with fatigue, edema and lab abnormalities; diagnosis reachable by history, exam, urinalysis and creatinine-based staging.", "kind": "disease", "category": "chronic kidney disease", "organ_systems": ["renal"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["familyMedicine"], "commonness": "very_common", "settings": ["clinic", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:30Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:56:08Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:56:15Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:56:33Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:56:46Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:56:52Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'echocardiogram' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'chest x-ray' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'magnetic resonance angiography of the renal arteries' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'echocardiogram' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'chest x-ray' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'magnetic resonance angiography of the renal arteries' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential acute-kidney-injury: no profile yet", "differential nephrotic-syndrome: no profile yet", "differential heart-failure: no profile yet", "differential hypothyroidism: no profile yet", "differential anemia-of-chronic-disease: no profile yet", "differential multiple-myeloma: no profile yet", "differential renal-artery-stenosis: no profile yet", "differential chronic-obstructive-pulmonary-disease: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 40, "typical_max": 85, "peak": "60–75", "possible_min": 5, "possible_max": 100}, "sex": "either", "demographics": ["More common with increasing age", "More common and more likely to progress to kidney failure in Black and Hispanic patients in the US", "Often detected incidentally on routine labs"], "risk_factors": [{"text": "Diabetes", "strength": "strong"}, {"text": "High blood pressure", "strength": "strong"}, {"text": "Family history of kidney failure", "strength": "strong"}, {"text": "Age over 60", "strength": "moderate"}, {"text": "Obesity", "strength": "moderate"}, {"text": "Prior acute kidney injury", "strength": "moderate"}, {"text": "Recurrent kidney stones or urinary obstruction", "strength": "moderate"}, {"text": "Smoking", "strength": "weak"}, {"text": "Frequent NSAID use", "strength": "weak"}], "comorbidities": ["Diabetes mellitus", "Hypertension", "Heart failure", "Coronary artery disease", "Obesity", "Gout", "Anemia", "Peripheral arterial disease"], "family_history": ["Kidney failure requiring dialysis in a relative", "Polycystic kidney disease", "Diabetes in the family"], "social_history": ["Smoking", "Low income or limited access to primary care", "Diet high in processed foods and salt"], "exposures": ["Long-term NSAIDs", "Nephrotoxic medications or contrast dye", "Heavy metals or industrial solvents (uncommon)"], "risk_medications": ["ibuprofen", "naproxen", "lisinopril", "losartan", "metformin", "furosemide", "omeprazole"]}, "presentation": {"chief_complaints": [{"text": "I've been feeling tired all the time", "frequency": "common"}, {"text": "My ankles and feet are swollen", "frequency": "common"}, {"text": "My doctor said my kidney numbers were off on my blood test", "frequency": "common"}, {"text": "I'm up all night going to the bathroom", "frequency": "sometimes"}, {"text": "I've been itching all over", "frequency": "sometimes"}, {"text": "I just don't have much of an appetite lately", "frequency": "sometimes"}, {"text": "I get short of breath just walking to the mailbox", "frequency": "sometimes"}], "hpi": {"onset": "Gradual and silent; usually found on routine labs or when a complication appears", "duration": "Kidney damage present for more than 3 months by definition; symptoms often develop over months to years", "progression": "Slowly progressive; many patients have no symptoms until kidney function is well below half of normal, and symptoms worsen as function declines further", "location": "Generalized; swelling in the legs, ankles, and around the eyes", "radiation": "Not applicable", "quality": "Vague tiredness, puffiness, poor appetite, and itching rather than a discrete pain", "severity": "Mild at first; can become disabling in advanced disease", "timing": "Fatigue worse through the day; nocturia most nights; itching worse at night", "aggravating": ["Exertion", "High-salt meals", "Missing dialysis or medications", "NSAID use"], "relieving": ["Rest", "Leg elevation", "Diuretics", "Dialysis (in advanced disease)"], "associated_symptoms": [{"text": "Fatigue and low energy", "frequency": "common"}, {"text": "Swelling of the legs, ankles, or feet", "frequency": "common"}, {"text": "Puffy eyes in the morning", "frequency": "sometimes"}, {"text": "Waking at night to urinate", "frequency": "common"}, {"text": "Foamy or bubbly urine", "frequency": "sometimes"}, {"text": "Poor appetite or early fullness", "frequency": "sometimes"}, {"text": "Nausea", "frequency": "sometimes"}, {"text": "Itching", "frequency": "sometimes"}, {"text": "Shortness of breath with activity", "frequency": "sometimes"}, {"text": "Muscle cramps, especially at night", "frequency": "sometimes"}, {"text": "Trouble concentrating or feeling foggy", "frequency": "sometimes"}, {"text": "Weight gain from fluid", "frequency": "sometimes"}, {"text": "Restless legs at night", "frequency": "rare"}, {"text": "Metallic taste or bad breath", "frequency": "rare"}], "pertinent_negatives": ["Burning or pain with urination", "Blood in the urine", "Colicky flank pain radiating to the groin", "Fever or chills", "Sudden onset over hours to days", "Recent severe diarrhea or vomiting with dehydration", "New use of a medication known to harm the kidneys", "Passing very little urine (unless far advanced)"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Tiredness", "frequency": "common"}, {"text": "Poor appetite", "frequency": "sometimes"}, {"text": "Feeling cold", "frequency": "sometimes"}], "negatives": ["Fever", "Night sweats", "Unintentional weight loss"]}, {"system": "cardiovascular", "positives": [{"text": "Swelling in the legs and ankles", "frequency": "common"}, {"text": "Shortness of breath with activity", "frequency": "sometimes"}, {"text": "Chest pressure with exertion", "frequency": "sometimes"}], "negatives": ["Chest pain at rest", "Palpitations", "Fainting"], "argues_against": ["Sudden crushing chest pain"]}, {"system": "respiratory", "positives": [{"text": "Shortness of breath when active", "frequency": "sometimes"}, {"text": "Cough at night when lying flat", "frequency": "sometimes"}], "negatives": ["Coughing up blood", "Pleuritic chest pain", "Wheezing"], "argues_against": ["Chronic productive cough with smoking history"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea", "frequency": "sometimes"}, {"text": "Feeling full quickly", "frequency": "sometimes"}, {"text": "Metallic taste", "frequency": "rare"}], "negatives": ["Vomiting blood", "Black stools", "Severe abdominal pain", "Diarrhea"], "argues_against": ["Bloody diarrhea with fever"]}, {"system": "genitourinary", "positives": [{"text": "Waking at night to urinate", "frequency": "common"}, {"text": "Foamy urine", "frequency": "sometimes"}, {"text": "Less urine than usual", "frequency": "sometimes"}], "negatives": ["Painful urination", "Visible blood in urine", "Urgency", "Flank pain"], "argues_against": ["Dysuria with frequency suggesting urinary tract infection", "Colicky flank pain suggesting kidney stone"]}, {"system": "musculoskeletal", "positives": [{"text": "Muscle cramps", "frequency": "sometimes"}, {"text": "Bone or joint aches", "frequency": "sometimes"}], "negatives": ["Joint swelling and redness", "Morning stiffness lasting hours"], "argues_against": ["Inflammatory arthritis"]}, {"system": "skin", "positives": [{"text": "Itching all over", "frequency": "sometimes"}, {"text": "Dry skin", "frequency": "sometimes"}, {"text": "Easy bruising", "frequency": "rare"}], "negatives": ["Rash", "New blisters", "Skin ulcers"], "argues_against": ["Vasculitic rash with fever"]}, {"system": "neurologic", "positives": [{"text": "Trouble concentrating", "frequency": "sometimes"}, {"text": "Restless legs at night", "frequency": "rare"}, {"text": "Numbness or tingling in the feet", "frequency": "sometimes"}], "negatives": ["New weakness on one side", "Seizures", "Confusion or drowsiness"], "argues_against": ["Acute stroke symptoms"]}, {"system": "psychiatric", "positives": [{"text": "Feeling down or discouraged", "frequency": "sometimes"}, {"text": "Trouble sleeping", "frequency": "sometimes"}], "negatives": ["Suicidal thoughts", "Hallucinations"]}, {"system": "hematologic", "positives": [{"text": "Looking pale", "frequency": "sometimes"}, {"text": "Bruising easily", "frequency": "rare"}], "negatives": ["Bleeding from the gums or nose", "Blood clots in the legs"]}, {"system": "endocrine", "positives": [{"text": "Increased thirst", "frequency": "sometimes"}, {"text": "Frequent urination during the day", "frequency": "sometimes"}], "negatives": ["Heat intolerance", "Tremor", "Unexplained weight loss with increased appetite"]}]}, "exam": {"general": {"mild": "Comfortable, no distress; may look well with only incidental lab abnormalities", "moderate": "Mildly fatigued, pale conjunctivae, subtle periorbital puffiness", "severe": "Ill-appearing, pale, sallow complexion, noticeable puffiness of face and hands, may appear short of breath at rest", "critical": "Lethargic, markedly pale, generalized edema, uremic appearance with sallow or grayish skin, possible confusion or asterixis"}, "findings": [{"id": "conjunctival-pallor", "region": "heent", "maneuver": "Inspect the palpebral conjunctivae and mucous membranes", "finding": "Pallor of the conjunctivae", "frequency": "common", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "periorbital-edema", "region": "heent", "maneuver": "Inspect the face and periorbital area, especially in the morning", "finding": "Periorbital puffiness", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "optional"}, {"id": "scleral-icterus-absent", "region": "heent", "maneuver": "Inspect the sclerae in natural light", "finding": "No scleral icterus", "frequency": "almost_always", "significance": "neutral", "importance": "optional"}, {"id": "elevated-jvp", "region": "neck", "maneuver": "Measure the jugular venous pressure with the patient at 30–45 degrees", "finding": "Elevated jugular venous pressure", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "hypertension-exam", "region": "cardiac", "maneuver": "Measure blood pressure in both arms with an appropriately sized cuff", "finding": "Elevated blood pressure", "frequency": "common", "significance": "supports", "importance": "essential"}, {"id": "s3-gallop", "region": "cardiac", "maneuver": "Auscultate the heart at the apex with the bell", "finding": "S3 gallop suggesting volume overload", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "pericardial-rub", "region": "cardiac", "maneuver": "Auscultate the heart at the left lower sternal border with the diaphragm", "finding": "Pericardial friction rub", "frequency": "rare", "min_severity": "critical", "significance": "supports", "importance": "important"}, {"id": "crackles", "region": "lung", "maneuver": "Auscultate the lung bases posteriorly", "finding": "Fine crackles at the bases", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "pleural-effusion-dullness", "region": "lung", "maneuver": "Percuss the lung bases and assess tactile fremitus", "finding": "Dullness to percussion with decreased breath sounds at the base", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "optional"}, {"id": "uremic-fetor", "region": "general", "maneuver": "Note the patient's breath odor during the interview", "finding": "Fetid or ammoniacal breath odor", "frequency": "rare", "min_severity": "critical", "significance": "supports", "importance": "optional"}, {"id": "abdominal-bruit", "region": "abdomen", "maneuver": "Auscultate over the epigastrium and 