insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$common-cold$rounds_kb$, $rounds_kb$Common Cold$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, array[$rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$]::text[], array[$rounds_kb$respiratory$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "common-cold", "triage": {"name": "Common Cold", "case_suitable": true, "reason": "Extremely common upper respiratory infection with classic history and exam; good for teaching viral URI and antibiotic stewardship.", "kind": "disease", "category": "viral infection", "organ_systems": ["respiratory"], "primary_clerkship": "familyMedicine", "secondary_clerkships": ["pediatrics", "internalMedicine"], "commonness": "very_common", "settings": ["clinic", "pediatric_clinic"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:40Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:57:34Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:57:39Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:57:43Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:57:53Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T04:57:59Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["differential influenza: no profile yet", "differential covid-19: no profile yet", "differential acute-bacterial-sinusitis: no profile yet", "differential streptococcal-pharyngitis: no profile yet", "differential community-acquired-pneumonia: no profile yet", "differential allergic-rhinitis: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 1, "typical_max": 75, "peak": "children under 10 and adults with young children at home", "possible_min": 0, "possible_max": 100}, "sex": "either", "demographics": ["Children average 5–7 colds per year; adults average 2–3", "More frequent in households with school-aged children", "More common in fall, winter, and early spring in temperate climates"], "risk_factors": [{"text": "Close contact with a person who has a cold", "strength": "strong"}, {"text": "Having young children at home or working in childcare or schools", "strength": "strong"}, {"text": "Crowded indoor settings such as dormitories, barracks, or offices", "strength": "moderate"}, {"text": "Touching the face with unwashed hands after contact with contaminated surfaces", "strength": "moderate"}, {"text": "Cigarette smoke exposure, including secondhand smoke", "strength": "moderate"}, {"text": "Fall or winter season", "strength": "weak"}], "comorbidities": ["Asthma", "Chronic obstructive pulmonary disease", "Allergic rhinitis"], "family_history": [], "social_history": ["Household members or coworkers with similar symptoms in the past week", "Children in daycare or school"], "exposures": ["Sick contacts at home, work, or school", "Recent air travel or crowded gatherings"], "risk_medications": []}, "presentation": {"chief_complaints": [{"text": "My nose is stuffy and running", "frequency": "almost_always"}, {"text": "My throat is scratchy and sore", "frequency": "common"}, {"text": "I keep sneezing", "frequency": "common"}, {"text": "I have a cough that won't quit", "frequency": "common"}, {"text": "I feel worn down and my head hurts", "frequency": "sometimes"}], "hpi": {"onset": "Gradual over one to two days, often starting with a scratchy throat or sneezing", "duration": "Symptoms peak in 2–3 days and usually resolve within 7–10 days; cough may linger up to 2 weeks", "progression": "Sore throat and sneezing come first, then nasal congestion and runny nose build over the next day or two, followed by cough; symptoms then slowly improve", "location": "Nose, throat, and upper chest", "radiation": "Not applicable", "quality": "Scratchy throat, watery then thicker nasal drainage, dry or mildly productive cough", "severity": "Mild; annoying but does not keep most people from daily activities", "timing": "Continuous through the day, often worse at night when lying down", "aggravating": ["Lying flat", "Cold air", "Talking a lot", "Smoke or strong odors"], "relieving": ["Rest", "Warm fluids", "Saline nasal spray", "Over-the-counter decongestants or acetaminophen"], "associated_symptoms": [{"text": "Runny nose with clear discharge", "frequency": "almost_always"}, {"text": "Nasal congestion", "frequency": "almost_always"}, {"text": "Sneezing", "frequency": "common"}, {"text": "Sore or scratchy throat", "frequency": "common"}, {"text": "Cough", "frequency": "common"}, {"text": "Headache", "frequency": "sometimes"}, {"text": "Low-grade fever, more often in children", "frequency": "sometimes"}, {"text": "Mild body aches", "frequency": "sometimes"}, {"text": "Postnasal drip", "frequency": "common"}, {"text": "Watery eyes", "frequency": "sometimes"}], "pertinent_negatives": ["High fever above 102°F", "Shortness of breath at rest", "Chest pain with breathing", "Coughing up blood", "Severe headache with stiff neck", "Facial pain or pressure over the sinuses", "Symptoms lasting more than 10 days without any improvement", "Symptoms that improved and then got worse again"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Feeling tired", "frequency": "common"}, {"text": "Low-grade fever", "frequency": "sometimes"}, {"text": "Chills", "frequency": "sometimes"}], "negatives": ["Weight loss", "Night sweats", "High fever above 102°F"], "argues_against": ["Influenza, which typically causes abrupt high fever and severe body aches"]}, {"system": "ent", "positives": [{"text": "Nasal congestion", "frequency": "almost_always"}, {"text": "Runny nose", "frequency": "almost_always"}, {"text": "Sneezing", "frequency": "common"}, {"text": "Sore throat", "frequency": "common"}, {"text": "Postnasal drip", "frequency": "common"}], "negatives": ["Ear pain", "Facial pain or pressure", "Loss of smell", "Severe throat pain preventing swallowing"], "argues_against": ["Bacterial sinusitis", "Streptococcal pharyngitis", "Otitis media"]}, {"system": "respiratory", "positives": [{"text": "Cough", "frequency": "common"}, {"text": "Hoarse voice", "frequency": "sometimes"}], "negatives": ["Shortness of breath at rest", "Wheezing", "Coughing up blood", "Chest pain with breathing"], "argues_against": ["Pneumonia", "Acute bronchitis with significant dyspnea", "Asthma exacerbation"]}, {"system": "eyes", "positives": [{"text": "Watery eyes", "frequency": "sometimes"}], "negatives": ["Purulent eye discharge", "Eye pain", "Vision changes"], "argues_against": ["Bacterial conjunctivitis"]}, {"system": "neurologic", "positives": [{"text": "Headache", "frequency": "sometimes"}], "negatives": ["Stiff neck", "Confusion", "Severe headache", "Light sensitivity"], "argues_against": ["Meningitis"]}, {"system": "gastrointestinal", "positives": [{"text": "Decreased appetite", "frequency": "sometimes"}], "negatives": ["Vomiting", "Diarrhea", "Abdominal pain"], "argues_against": ["Viral gastroenteritis"]}], "atypical": [{"population": "infants", "how_it_differs": "Infants cannot describe symptoms; they present with fussiness, poor feeding, nasal congestion interfering with feeding, and sometimes fever. Symptoms may last longer than in older children.", "missing_classic_features": ["Sore throat complaint", "Headache complaint"]}, {"population": "children", "how_it_differs": "Children often have higher fevers than adults and may have more prominent cough and nasal symptoms; they may also develop ear infections or sinusitis as complications.", "missing_classic_features": []}, {"population": "older_adults", "how_it_differs": "Fever may be blunted or absent, and symptoms can be milder but complications such as pneumonia are more likely.", "missing_classic_features": ["Fever"]}, {"population": "immunocompromised", "how_it_differs": "Colds can be more severe, last longer, and progress to lower respiratory infection or pneumonia more often.", "missing_classic_features": []}]}, "exam": {"general": {"mild": "Well-appearing, alert, speaking in full sentences; may sniffle or wipe nose", "moderate": "Mildly uncomfortable, occasional cough, slightly hoarse voice, no distress", "severe": "Tired-appearing with frequent coughing, but no respiratory distress at rest", "critical": "Not applicable; the common cold does not produce a critical general appearance — if the patient looks toxic or is in respiratory distress, consider another diagnosis"}, "findings": [{"id": "nasal-mucosa-edema", "region": "heent", "maneuver": "Inspect the nasal mucosa with a light and nasal speculum", "finding": "Erythematous, swollen nasal mucosa with clear to whitish secretions", "frequency": "almost_always", "significance": "supports", "importance": "essential"}, {"id": "clear-rhinorrhea", "region": "heent", "maneuver": "Inspect the nares and ask the patient to sniff", "finding": "Clear, watery nasal discharge", "frequency": "almost_always", "significance": "supports", "importance": "important"}, {"id": "pharyngeal-erythema", "region": "heent", "maneuver": "Inspect the posterior pharynx with a tongue blade and light", "finding": "Mild diffuse erythema of the posterior pharynx without exudate", "frequency": "common", "significance": "supports", "importance": "important"}, {"id": "no-tonsillar-exudate", "region": "heent", "maneuver": "Inspect the tonsils and posterior pharynx", "finding": "No tonsillar exudate or swelling", "frequency": "al