insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$coronary-artery-disease$rounds_kb$, $rounds_kb$Coronary Artery Disease$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$surgery$rounds_kb$]::text[], array[$rounds_kb$cardiovascular$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "coronary-artery-disease", "triage": {"name": "Coronary Artery Disease", "case_suitable": true, "reason": "Core cardiology diagnosis reachable from chest pain history, risk factors, exam, ECG and troponin; drives major management decisions.", "kind": "disease", "category": "ischemic heart disease", "organ_systems": ["cardiovascular"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["emergency", "familyMedicine", "surgery"], "commonness": "very_common", "settings": ["clinic", "emergency", "inpatient"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:50Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:00:23Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:00:29Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:00:42Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:00:54Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:01:01Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: renamed 'ecg' to 'ECG'", "auto-repaired: workup: renamed 'ct_abdomen_pelvis_contrast' to 'Ct abdomen pelvis contrast'", "auto-repaired: workup: 'chest x-ray' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'd_dimer' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'chest x-ray' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "auto-repaired: workup: 'd_dimer' was in ['supporting', 'not_indicated'], kept ['not_indicated', 'supporting']", "differential gastroesophageal-reflux-disease: no profile yet", "differential pulmonary-embolism: no profile yet", "differential aortic-dissection: no profile yet", "differential pericarditis: no profile yet", "differential costochondritis: no profile yet", "differential esophageal-spasm: no profile yet", "differential panic-attack: no profile yet", "differential anemia: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 45, "typical_max": 85, "peak": "55–75", "possible_min": 20, "possible_max": 100}, "sex": "male_predominant", "demographics": ["Men tend to develop symptomatic CAD about a decade earlier than women", "Women often present around or after menopause, and microvascular disease is more common in women", "Prevalence rises steadily with age in both sexes", "Higher rates among non-Hispanic White and non-Hispanic Black adults than among some other US groups"], "risk_factors": [{"text": "High blood pressure", "strength": "strong"}, {"text": "High LDL cholesterol", "strength": "strong"}, {"text": "Diabetes or high blood glucose", "strength": "strong"}, {"text": "Current or past smoking or tobacco use", "strength": "strong"}, {"text": "Older age", "strength": "strong"}, {"text": "Male sex", "strength": "moderate"}, {"text": "Family history of early heart disease in a parent or sibling", "strength": "moderate"}, {"text": "Overweight or obesity", "strength": "moderate"}, {"text": "Physical inactivity", "strength": "moderate"}, {"text": "Diet high in saturated fat", "strength": "moderate"}, {"text": "Chronic kidney disease", "strength": "moderate"}, {"text": "Low HDL cholesterol", "strength": "weak"}, {"text": "Chronic inflammatory conditions such as rheumatoid arthritis or lupus", "strength": "weak"}], "comorbidities": ["Hypertension", "Type 2 diabetes", "Hyperlipidemia", "Chronic kidney disease", "Peripheral artery disease", "Prior stroke or transient ischemic attack", "Heart failure", "Metabolic syndrome"], "family_history": ["Heart attack, bypass surgery, or stent in a parent or sibling before age 50–55", "Sudden cardiac death in a close relative", "Familial hypercholesterolemia"], "social_history": ["Current or former cigarette smoking", "Sedentary work and little leisure exercise", "High chronic stress or long work hours", "Heavy alcohol use"], "exposures": ["Secondhand smoke", "Long-term air pollution"], "risk_medications": ["estrogen", "testosterone", "prednisone", "ibuprofen", "naproxen", "celecoxib"]}, "presentation": {"chief_complaints": [{"text": "I get this pressure in my chest when I walk up the stairs", "frequency": "almost_always"}, {"text": "My chest feels tight and heavy when I exert myself", "frequency": "common"}, {"text": "I get short of breath doing things I used to do easily", "frequency": "common"}, {"text": "I feel a squeezing in the middle of my chest that goes into my left arm", "frequency": "common"}, {"text": "I just feel worn out and can't keep up anymore", "frequency": "sometimes"}], "hpi": {"onset": "Gradual over weeks to months; often first noticed during a specific activity", "duration": "Symptoms usually present for weeks to months when stable; minutes to hours when unstable", "progression": "Stable pattern: predictable discomfort with a similar level of exertion, relieved within minutes by rest. Unstable pattern: symptoms come on with less effort, last longer, or occur at rest — a change from the usual pattern", "location": "Mid-chest or substernal, sometimes described as the whole chest or upper abdomen", "radiation": "May spread to the left shoulder and arm, both arms, neck, jaw, back, or upper abdomen", "quality": "Pressure, tightness, squeezing, heaviness, or a band-like sensation; often not described as sharp pain", "severity": "Mild to moderate, typically 3–6/10; severe and unrelenting when it represents an acute coronary syndrome", "timing": "Comes on with exertion, emotional stress, cold weather, or after a heavy meal; lasts 2–10 minutes with stable angina and resolves with rest or nitroglycerin", "aggravating": ["Walking uphill or climbing stairs", "Carrying groceries or heavy lifting", "Emotional stress or anger", "Cold weather", "Large meals", "Sexual activity"], "relieving": ["Resting or sitting down", "Nitroglycerin under the tongue", "Stopping the activity"], "associated_symptoms": [{"text": "Shortness of breath with the chest discomfort", "frequency": "common"}, {"text": "Feeling unusually tired with activity", "frequency": "common"}, {"text": "Lightheadedness or dizziness", "frequency": "sometimes"}, {"text": "Sweating or clamminess during an episode", "frequency": "sometimes"}, {"text": "Nausea or a queasy stomach during an episode", "frequency": "sometimes"}, {"text": "Palpitations or a racing heartbeat", "frequency": "sometimes"}, {"text": "Fainting", "frequency": "rare"}], "pertinent_negatives": ["Chest pain that is sharp and stabbing", "Pain that changes with breathing, coughing, or twisting the torso", "Pain reproduced by pressing on the chest wall", "Pain that is worst when lying flat and better sitting forward", "Burning pain that follows meals and wakes them at night", "Pain that comes only with swallowing", "Recent viral illness with fever", "Sudden tearing pain that started at maximum intensity", "Pain that is only in one small spot and lasts seconds"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Fatigue with activity", "frequency": "common"}, {"text": "Sweating during episodes", "frequency": "sometimes"}], "negatives": ["Unintentional weight loss", "Fever", "Night sweats"]}, {"system": "cardiovascular", "positives": [{"text": "Chest pressure with exertion", "frequency": "almost_always"}, {"text": "Palpitations", "frequency": "sometimes"}, {"text": "Swelling in the ankles", "frequency": "sometimes"}], "negatives": ["Chest pain at rest in the stable pattern", "Pain that changes with position", "Pain reproduced by pressing on the chest"], "argues_against": ["Sharp positional pain worsened by breathing", "Chest wall tenderness on palpation"]}, {"system": "respiratory", "positives": [{"text": "Shortness of breath with exertion", "frequency": "common"}], "negatives": ["Cough producing sputum", "Coughing up blood", "Pleuritic pain with deep breaths", "Wheezing"], "argues_against": ["Pleuritic chest pain with a recent viral illness", "Sudden shortness of breath with leg swelling and recent immobility"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea during episodes", "frequency": "sometimes"}, {"text": "Heartburn or indigestion", "frequency": "sometimes"}], "negatives": ["Vomiting blood", "Black or bloody stools", "Pain that reliably follows meals", "Difficulty swallowing"], "argues_against": ["Burning pain that wakes them at night and improves with antacids", "Pain that comes only with swallowing"]}, {"system": "neurologic", "positives": [{"text": "Lightheadedness with episodes", "frequency": "sometimes"}], "negatives": ["Focal weakness or numbness", "Slurred speech", "Loss of consciousness", "Sudden severe headache"], "argues_against": ["Focal neurologic deficits suggesting a cerebrovascular cause"]}, {"system": "musculoskeletal", "positives": [], "negatives": ["Chest wall tenderness", "Pain worse with arm movement or twisting", "Recent trauma to the chest"], "argues_against": ["Reproducible chest wall pain on palpation", "Pain that follows a fall or strain"]}]}, "exam": {"general": {"mild": "Comfortable, no distress at rest; normal habitus or overweight", "moderate": "Mildly uncomfortable when describing exertional symptoms, otherwise comfortable at rest", "severe": "Diaphoretic and anxious, clutching the chest, prefers to sit upright", "critical": "Ill-appearing, pale and clammy, agitated or lethargic, may be hypotensive"}, "findings": [{"id": "no-chest-wall-tenderness", "region": "musculoskeletal", "maneuver": "Palpate the anterior chest wall and reproduce symptoms by pressing on the sternum and ribs", "finding": "No reproducible chest wall tenderness", "frequency": "almost_always", "significance": "neutral", "importance": "important"}, {"id": "normal-heart-sounds", "region": "cardiac", "maneuver": "Auscultate the four valve areas with the diaphragm and bell", "finding": "Normal S1 and S2 without murmur, rub, or gallop", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "s4-gallop", "region": "cardiac", "maneuver": "Auscultate the apex with the bell in the left lateral decubitus position", "finding": "Fourth heart sound (atrial gallop)", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "s3-gallop", "region": "cardiac", "maneuver": "Auscultate the apex with the bell", "finding": "Third heart sound suggesting left ventricular dysfunction", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "mitral-regurgitation-murmur", "region": "cardiac", "maneuver": "Auscultate the apex with the diaphragm", "finding": "Holosystolic murmur radiating to the axilla", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "carotid-bruit", "region": "neck", "maneuver": "Auscultate over the carotid arteries and palpate the upstroke", "finding": "Carotid bruit or diminished upstroke, suggesting concomitant atherosclerosis", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "optional"}, {"id": "jugular-venous-distention", "region": "neck", "maneuver": "Inspect the internal jugular vein at 45 degrees", "finding": "Elevated jugular venous pressure suggesting heart failure", "frequency": "rare", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "pulmonary-crackles", "region": "lung", "maneuver": "Auscultate the lung bases", "finding": "Bibasilar crackles suggesting pulmonary congestion", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "clear-lungs", "region": "lung", "maneuver": "Auscultate all lung fields", "finding": "Clear breath sounds without crackles or wheeze", "frequency": "common", "significance": "neutral", "importance": "optional"}, {"id": "peripheral-edema", "region": "extremities", "maneuver": "Press over the dorsum of each foot and the pretibial area", "finding": "Pitting edema suggesting right heart failure", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "diminished-pedal-pulses", "region": "extremities", "maneuver": "Palpate the dorsalis pedis and posterior tibial pulses", "finding": "Diminished or absent pedal pulses suggesting peripheral artery disease", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "optional"}, {"id": "xanthomas", "region": "skin", "maneuver": "Inspect the eyelids, elbows, knees, and Achilles tendons", "finding": "Xanthelasma or tendon xanthomas suggesting familial hypercholesterolemia", "frequency": "rare", "significance": "supports", "importance": "optional"}, {"id": "no-fever", "region": "general", "maneuver": "Measure temperature and inspect for systemic signs", "finding": "Afebrile without rash or joint swelling", "frequency": "almost_always", "significance": "neut