al"}, {"id": "hypoxia-pulse-ox", "region": "lung", "maneuver": "Place a pulse oximeter on the finger and record the reading", "finding": "Oxygen saturation below 94% on room air", "frequency": "common", "min_severity": "moderate", "significance": "strongly_supports", "importance": "essential"}, {"id": "accessory-muscle-use", "region": "lung", "maneuver": "Observe the patient's breathing at rest", "finding": "Use of accessory muscles of respiration, nasal flaring, or intercostal retractions", "frequency": "sometimes", "min_severity": "severe", "significance": "supports", "importance": "important"}, {"id": "diffuse-crackles", "region": "lung", "maneuver": "Auscultate all lung fields with the patient breathing deeply through the mouth", "finding": "Diffuse bilateral crackles or rales, often at the bases", "frequency": "sometimes", "min_severity": "moderate", "significance": "supports", "importance": "important"}, {"id": "normal-lung-sounds", "region": "lung", "maneuver": "Auscultate all lung fields", "finding": "Clear breath sounds without crackles, wheezes, or focal dullness", "frequency": "common", "significance": "neutral", "importance": "important"}, {"id": "no-focal-consolidation", "region": "lung", "maneuver": "Percuss and auscultate for focal dullness with egophony or bronchial breath sounds", "finding": "No focal consolidation signs", "frequency": "common", "significance": "argues_against", "importance": "important"}, {"id": "anosmia-test", "region": "heent", "maneuver": "Ask the patient to identify a familiar scent or taste, or ask directly about loss of smell and taste", "finding": "Reduced or absent sense of smell and/or taste", "frequency": "common", "significance": "strongly_supports", "importance": "important"}, {"id": "pharyngeal-erythema", "region": "heent", "maneuver": "Inspect the oropharynx with a light and tongue blade", "finding": "Mild diffuse pharyngeal erythema without exudate or asymmetry", "frequency": "sometimes", "significance": "supports", 