lity": "xray", "findings": [{"text": "Normal or no acute cardiopulmonary process", "frequency": "common"}, {"text": "Bilateral patchy or hazy opacities, often peripheral and basilar", "frequency": "sometimes"}, {"text": "Focal lobar consolidation suggesting bacterial superinfection", "frequency": "rare"}, {"text": "Small pleural effusion", "frequency": "rare"}]}, {"study": "CT chest without IV contrast", "modality": "ct", "preferred_when": "When the diagnosis is uncertain, another cause is suspected, or complications are being evaluated", "findings": [{"text": "Bilateral peripheral ground-glass opacities", "frequency": "common"}, {"text": "Multifocal or dependent consolidation", "frequency": "sometimes"}, {"text": "Crazy-paving pattern with interlobular septal thickening", "frequency": "sometimes"}, {"text": "No mediastinal lymphadenopathy or cavitation", "frequency": "common"}, {"text": "Pulmonary embolism (filling defect in pulmonary arteries) when CT angiography is performed", "frequency": "rare"}]}, {"study": "CT pulmonary angiography", "modality": "ct", "preferred_when": "Suspected pulmonary embolism (sudden worsening hypoxia, pleuritic pain, high D-dimer)", "findings": [{"text": "Filling defect in one or more pulmonary arteries", "frequency": "rare"}, {"text": "Right ventricular enlargement with interventricular septal bowing", "frequency": "rare"}]}, {"study": "Lung ultrasound", "modality": "ultrasound", "preferred_when": "Bedside assessment of hypoxia when transport is limited", "findings": [{"text": "Bilateral B-lines in a patchy distribution", "frequency": "common"}, {"text": "Subpleural consolidations", "frequency": "sometimes"}, {"text": "Thickened pleural line", "frequency": "sometimes"}]}, {"study": "Transthoracic echocardiogram", "modality": "echo", "preferred_when": "Suspected myocarditis, heart failure, or hemodynamic instability", "findings": [{"text": "Normal systolic function", "frequency": "common"}, {"text": "Global or regional left ventricular dysfunction", "frequency": "rare"}, {"text": "Pericardial effusion", "frequency": "rare"}]}], "workup": {"initial": [{"test": "cbc", "why": "Looks for lymphopenia, leukocytosis, and thrombocytopenia"}, {"test": "bmp", "why": "Assesses hydration, kidney function, and electrolytes"}, {"test": "crp", "why": "Baseline inflammatory marker that helps gauge severity"}, {"test": "Rapid SARS-CoV-2 antigen test", "why": "Fast bedside test when symptoms are present; a negative result in a high-risk patient needs a molecular test"}, {"test": "SARS-CoV-2 nucleic acid amplification test (PCR)", "why": "Most sensitive test to confirm infection"}, {"test": "Rapid influenza test", "why": "Common look-alike that changes treatment", "only_if": "influenza is circulating or the patient has typical influenza symptoms"}, {"test": "Chest x-ray, posteroanterior and lateral", "why": "Looks for pneumonia or another cause of hypoxia", "only_if": "hypoxia, abnormal lung exam, or suspected pneumonia"}], "confirmatory": [], "supporting": [{"test": "procalcitonin", "why": "Low value supports a viral cause and argues against bacterial coinfection", "only_if": "bacterial pneumonia or sepsis is being considered"}, {"test": "d_dimer", "why": "Elevated in severe disease; very high values raise concern for thromboembolism", "only_if": "severe disease or suspected pulmonary embolism"}, {"test": "abg", "why": "Quantifies oxygenation and ventilation in severe hypoxia or respiratory distress", "only_if": "severe hypoxia, respiratory distress, or concern for respiratory failure"}, {"test": "lactate", "why": "Assesses perfusion in severe or critical illness", "only_if": "hypotension, tachycardia, or concern for sepsis"}, {"test": "hs_tnt", "why": "Detects myocardial injury in severe disease", "only_if": "chest pain, ECG changes, or hemodynamic instability"}, {"test": "coag", "why": "Evaluates for coagulopathy in severe disease", "only_if": "bleeding, very high D-dimer, or critical illness"}, {"test": "CT chest without IV contrast", "why": "Clarifies an uncertain diagnosis or evaluates complications", "only_if": "diagnosis unclear, worsening hypoxia, or suspected complication"}, {"test": "CT pulmonary angiography", "why": "Confirms pulmonary embolism", "only_if": "pulmonary embolism is suspected"}, {"test": "Transthoracic echocardiogram", "why": "Evaluates cardiac function and pericardial effusion", "only_if": "suspected myocarditis, heart failure, or shock"}], "not_indicated": [{"test": "Rapid influenza test", "why": "Not needed when the presentation is clearly COVID-19 and influenza is not circulating", "only_if": "influenza is circulating or the patient has typical influenza symptoms"}, {"test": "Chest x-ray, posteroanterior and lateral", "why": "Not routine in mild illness with normal oxygen saturation and clear lungs", "only_if": "hypoxia, abnormal lung exam, or suspected pneumonia"}, {"test": "CT chest without IV contrast", "why": "Not a first-line test; radiation and contrast exposure without changing management in mild disease", "only_if": "diagnosis unclear, worsening hypoxia, or suspected complication"}, {"test": "CT pulmonary angiography", "why": "Not routine; only for suspected pulmonary embolism", "only_if": "pulmonary embolism is suspected"}, {"test": "Transthoracic echocardiogram", "why": "Not routine in uncomplicated disease", "only_if": "suspected myocarditis, heart failure, or shock"}, {"test": "abg", "why": "Not needed when pulse oximetry is adequate", "only_if": "severe hypoxia, respiratory distress, or concern for respiratory failure"}, {"test": "lactate", "why": "Not needed in stable patients with normal perfusion", "only_if": "hypotension, tachycardia, or concern for sepsis"}, {"test": "hs_tnt", "why": "Not routine without cardiac symptoms or instability", "only_if": "chest pain, ECG changes, or hemodynamic instability"}, {"test": "coag", "why": "Not routine in mild disease", "only_if": "bleeding, very high D-dimer, or critical illness"}, {"test": "procalcitonin", "why": "Not routine; does not diagnose COVID-19", "only_if": "bacterial pneumonia or sepsis is being considered"}, {"test": "d_dimer", "why": "Not routine in mild disease; often elevated from inflammation alone", "only_if": "severe disease or suspected pulmonary embolism"}, {"test": "Ct head", "why": "No role unless there is a focal neurologic deficit or altered mental status"}, {"test": "ua", "why": "No role unless urinary symptoms or another diagnosis is suspected"}], "decision_points": ["A negative rapid antigen test does not rule out COVID-19 when suspicion is high; confirm with a molecular test", "Pulse oximetry below 94% on room air marks moderate or worse disease and changes disposition", "Sudden worsening hypoxia or pleuritic chest pain should prompt evaluation for pulmonary embolism", "Chest pain with ECG changes or troponin elevation should prompt evaluation for myocarditis or myocardial infarction", "New confusion in an older adult is a red flag for severe disease even without fever or cough"], "criteria": [{"name": "SARS-CoV-2 infection categories (paraphrased)", "summary": "Confirmed infection requires a positive molecular or antigen test. Severity is classified by symptoms and oxygen needs: mild illness without hypoxia; moderate illness with lower respiratory involvement and oxygen saturation at or above 94% on room air; severe illness with oxygen saturation below 94%, respiratory rate at or above 30/min, or lung infiltrates involving more than half the lung fields; critical illness with respiratory failure, shock, or multiorgan dysfunction.", "items": ["Positive SARS-CoV-2 test", "Mild: no hypoxia or lower respiratory symptoms", "Moderate: lower respiratory symptoms with oxygen saturation at or above 94% on room air", "Severe: oxygen saturation below 94% on room air, respiratory rate at or above 30/min, or extensive lung infiltrates", "Critical: respiratory failure, shock, or multiorgan dysfunction"]}], "scores": ["curb_65", "qsofa", "news2"]}, "differential": [{"name": "Influenza", "slug": "influenza", "why_considered": "Fever, myalgias, sore throat, cough, and headache are nearly identical to COVID-19, and both circulate in the same seasons.", "must_not_miss": false, "discriminators": {"history": ["Abrupt onset over hours rather than 1–3 days", "Prominent myalgias and high fever at the start", "Loss of smell or taste is uncommon", "Known influenza exposure or circulating influenza in the community"], "exam": ["Similar: fever, pharyngeal erythema, clear lungs", "No anosmia on direct testing"], "labs": ["Positive rapid influenza test", "Lymphopenia can occur but is less characteristic", "Negative SARS-CoV-2 molecular test"], "imaging": ["Chest x-ray usually normal in uncomplicated disease"]}}, {"name": "Respiratory syncytial virus infection", "slug": "respiratory-syncytial-virus-infection", "why_considered": "Cough, congestion, sore throat, and low-grade fever, especially in older adults and young children.", "must_not_miss": false, "discriminators": {"history": ["Prominent nasal congestion and wheezing", "Gradual onset without prominent myalgias", "Loss of smell or taste is uncommon"], "exam": ["Wheezing or coarse breath sounds", "No anosmia"], "labs": ["Positive RSV test", "Negative SARS-CoV-2 molecular test"], "imaging": ["Chest x-ray usually normal or with hyperinflation"]}}, {"name": "Bacterial community-acquired pneumonia", "slug": "community-acquired-pneumonia", "why_considered": "Fever, cough, and dyspnea with hypoxia can look identical, and bacterial superinfection can complicate COVID-19.", "must_not_miss": true, "trigger": "Focal consolidation on exam or imaging, productive cough with colored sputum, or marked leukocytosis", "discriminators": {"history": ["Productive cough with thick colored sputum", "Pleuritic chest pain that is sharp and one-sided", "Sudden onset rather than gradual", "No loss of smell or taste"], "exam": ["Focal dullness, egophony, or bronchial breath sounds", "Focal crackles rather than diffuse bilateral crackles"], "labs": ["Leukocytosis with neutrophilia", "Elevated procalcitonin", "Negative SARS-CoV-2 molecular test"], "imaging": ["Focal lobar consolidation on chest x-ray or CT", "May have pleural effusion"]}}, {"name": "Pulmonary embolism", "slug": "pulmonary-embolism", "why_considered": "Sudden worsening dyspnea and hypoxia with chest discomfort can mimic severe COVID-19, and COVID-19 itself increases thromboembolic risk.", "must_not_miss": true, "trigger": "Sudden worsening hypoxia, pleuritic chest pain, tachycardia, or a very high D-dimer", "discriminators": {"history": ["Sudden onset of dyspnea rather than gradual worsening", "Pleuritic chest pain and hemoptysis", "Recent immobility, surgery, or known malignancy", "No fever or anosmia"], "exam": ["Tachycardia with clear lungs", "Signs of right heart strain such as jugular venous distension or a loud P2", "Unilateral leg swelling suggesting deep vein thrombosis"], "labs": ["Elevated D-dimer", "Elevated troponin or NT-proBNP from right heart strain", "Negative SARS-CoV-2 molecular test"], "imaging": ["Filling defect in pulmonary arteries on CT pulmonary angiography", "Right ventricular enlargement with septal bowing"]}}, {"name": "Myocarditis", "slug": "myocarditis", "why_considered": "Chest pain, dyspnea, and fatigue with troponin elevation can occur in COVID-19 and in other viral infections.", "must_not_miss": true, "trigger": "Chest pain with ECG changes or troponin elevation", "discriminators": {"history": ["Chest pain at rest or with exertion", "Palpitations or syncope", "Recent viral illness", "Less prominent cough and anosmia"], "exam": ["Tachycardia out of proportion to fever", "New murmur, gallop, or signs of heart failure", "Hypotension"], "labs": ["Elevated troponin and NT-proBNP", "Elevated inflammatory markers", "Negative SARS-CoV-2 molecular test if another virus is the cause"], "imaging": ["Global or regional left ventricular dysfunction on echocardiogram", "Pericardial effusion", "Late gadolinium enhancement on cardiac MRI"], "ecg": ["Diffuse ST elevation or depression with PR depression", "Diffuse T-wave inversions", "New bundle branch block or atrioventricular block"]}}, {"name": "Allergic rhinitis", "slug": "allergic-rhinitis", "why_considered": "Nasal congestion, sore throat, and cough can be mistaken for mild COVID-19.", "must_not_miss": false, "discriminators": {"history": ["Sneezing and itchy watery eyes as the main problem", "No fever or myalgias", "Recurrent seasonal pattern", "No loss of smell or taste"], "exam": ["Pale or bluish nasal mucosa", "Allergic shiners", "Clear lungs"], "labs": ["Negative SARS-CoV-2 molecular test", "Normal inflammatory markers"], "imaging": ["Not indicated"]}}, {"name": "Post-COVID conditions (long COVID)", "slug": "post-covid-conditions", "why_considered": "Persistent fatigue, brain fog, dyspnea, and cough after a COVID-19 illness can be confused with ongoing acute infection.", "must_not_miss": false, "discriminators": {"history": ["Symptoms lasting weeks to months after the acute illness", "No fever or acute worsening", "Often after a documented prior infection"], "exam": ["Often normal", "No hypoxia at rest"], "labs": ["Negative SARS-CoV-2 molecular test", "Inflammatory markers usually normal"], "imaging": ["Chest imaging usually normal or with residual scarring"]}}], "course": {"severity": {"mild": "Upper airway and constitutional symptoms without lower respiratory involvement or hypoxia; oxygen saturation at or above 94% on room air; able to manage at home", "moderate": "Lower respiratory involvement with cough and dyspnea but oxygen saturation at or above 94% on room air; may need monitoring and supportive care", "severe": "Oxygen saturation below 94% on room air, respiratory rate at or above 30/min, or lung infiltrates involving more than half the lung fields; requires hospitalization and oxygen", "critical": "Respiratory failure requiring mechanical ventilation, shock, or multiorgan dysfunction; requires intensive care"}, "red_flags": [{"finding": "Oxygen saturation below 94% on room air", "meaning": "Moderate or worse disease; changes disposition and need for oxygen"}, {"finding": "Respiratory rate at or above 30/min", "meaning": "Impending respiratory failure; needs urgent evaluation"}, {"finding": "New confusion or disorientation, especially in an older adult", "meaning": "Severe disease even without fever or cough; assess oxygenation and consider other causes"}, {"finding": "Sudden worsening hypoxia or pleuritic chest pain", "meaning": "Consider pulmonary embolism"}, {"finding": "Chest pain with ECG changes or troponin elevation", "meaning": "Consider myocarditis or myocardial infarction"}, {"finding": "Hypotension or lactate elevation", "meaning": "Shock or sepsis; needs immediate resuscitation"}, {"finding": "Rising CO2 on blood gas", "meaning": "Impending respiratory failure from fatigue"}], "complications": [{"name": "Acute respiratory distress syndrome", "timing": "early", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["Worsening hypoxia around days 5–10", "Diffuse bilateral opacities on imaging", "Increasing oxygen requirement"]}, {"name": "Bacterial superinfection or ventilator-associated pneumonia", "timing": "late", "seriousness": "serious", "frequency": "sometimes", "clues": ["New fever after initial improvement", "Productive cough with colored sputum", "Focal consolidation on imaging", "Elevated procalcitonin"]}, {"name": "Pulmonary embolism or venous thromboembolism", "timing": "any", "seriousness": "life_threatening", "frequency": "sometimes", "clues": ["Sudden worsening hypoxia", "Pleuritic chest pain", "Very high D-dimer", "Unilateral leg swelling"]}, {"name": "Myocarditis or myocardial injury", "timing": "any", "seriousness": "serious", "frequency": "rare", "clues": ["Chest pain", "Troponin elevation", "ECG changes", "New heart failure"]}, {"name": "Acute kidney injury", "timing": "any