insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$diabetes-type-2$rounds_kb$, $rounds_kb$Diabetes Type 2$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$, $rounds_kb$emergency$rounds_kb$]::text[], array[$rounds_kb$endocrine$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "diabetes-type-2", "triage": {"name": "Diabetes Type 2", "case_suitable": true, "reason": "Very common clinic presentation with subtle symptoms, screening labs and a broad complication differential; strong teaching case.", "kind": "disease", "category": "endocrine/metabolic", "organ_systems": ["endocrine"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["familyMedicine", "emergency"], "commonness": "very_common", "settings": ["clinic", "inpatient", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:16:59Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:05Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:12Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:23Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:41Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:04:47Z"}], "validation": {"status": "passed", "rule_errors": [], "review_issues": ["auto-repaired: workup: 'a1c' was in ['initial', 'confirmatory'], kept ['initial']", "auto-repaired: workup: 'glucose' was in ['initial', 'confirmatory'], kept ['initial']", "labs k: both high and low across severities", "differential type-1-diabetes: no profile yet", "differential diabetic-ketoacidosis: no profile yet", "differential hyperosmolar-hyperglycemic-state: no profile yet", "differential medication-induced-hyperglycemia: no profile yet", "differential stress-hyperglycemia: no profile yet", "differential cushing-syndrome: no profile yet", "differential hypothyroidism: no profile yet", "differential pancreatic-diabetes: no profile yet", "differential monogenic-diabetes: no profile yet", "differential gestational-diabetes: no profile yet"]}, "review": {"status": "pending"}}, "patient": {"age": {"typical_min": 35, "typical_max": 80, "peak": "45–65", "possible_min": 10, "possible_max": 100}, "sex": "either", "demographics": ["More common in Black, Hispanic/Latino, American Indian, Asian American, and Pacific Islander adults in the US", "Slightly more common in men in middle age; more common in women at older ages", "Increasingly diagnosed in adolescents and young adults, especially with obesity"], "risk_factors": [{"text": "Overweight or obesity", "strength": "strong"}, {"text": "Prediabetes (A1C 5.7–6.4% or fasting glucose 100–125 mg/dL)", "strength": "strong"}, {"text": "First-degree relative with type 2 diabetes", "strength": "strong"}, {"text": "Age over 45", "strength": "moderate"}, {"text": "Physically inactive lifestyle", "strength": "moderate"}, {"text": "History of gestational diabetes or a baby weighing 9 pounds or more at birth", "strength": "strong"}, {"text": "Polycystic ovary syndrome", "strength": "moderate"}, {"text": "High blood pressure or high triglycerides with low HDL cholesterol", "strength": "moderate"}, {"text": "Acanthosis nigricans (dark velvety skin at the neck or armpits)", "strength": "moderate"}, {"text": "Chronic use of glucocorticoids or atypical antipsychotics", "strength": "weak"}], "comorbidities": ["Hypertension", "Hyperlipidemia", "Coronary artery disease", "Stroke", "Metabolic syndrome", "Nonalcoholic fatty liver disease", "Obstructive sleep apnea", "Polycystic ovary syndrome", "Depression"], "family_history": ["Type 2 diabetes in a parent or sibling", "Gestational diabetes in the mother"], "social_history": ["Sedentary work or little regular exercise", "Diets high in refined carbohydrates and sugar-sweetened drinks", "Limited access to healthy food or preventive care"], "exposures": [], "risk_medications": ["prednisone", "prednisolone", "dexamethasone", "olanzapine", "risperidone", "quetiapine", "hydrochlorothiazide", "metoprolol", "tacrolimus", "sirolimus"]}, "presentation": {"chief_complaints": [{"text": "I've been so thirsty lately", "frequency": "common"}, {"text": "I'm up all night going to the bathroom", "frequency": "common"}, {"text": "I just feel tired all the time", "frequency": "common"}, {"text": "My doctor said my sugar was high on my blood work", "frequency": "common"}, {"text": "I've lost some weight without trying", "frequency": "sometimes"}, {"text": "My vision has been blurry", "frequency": "sometimes"}, {"text": "The sore on my foot just won't heal", "frequency": "sometimes"}], "hpi": {"onset": "Gradual, often over months to years; many patients cannot name when it started", "duration": "Symptoms usually present for months; a third or more of patients have no symptoms and are found on routine labs", "progression": "Slowly worsening thirst, urination and fatigue; symptoms may be mild enough to ignore until a routine visit or a complication brings them in", "location": "Whole-body; foot numbness or tingling is in the feet and hands", "radiation": "Not applicable", "quality": "Thirst is constant and hard to satisfy; urination is frequent, including at night; fatigue is a heavy, low-energy feeling", "severity": "Mild to moderate; patients often say they thought it was just getting older", "timing": "Thirst and urination are worse at night and after meals; fatigue is worse in the afternoon", "aggravating": ["Sugary drinks and large meals", "Hot weather", "Being inactive"], "relieving": ["Drinking water briefly helps the thirst", "Rest helps the tiredness a little"], "associated_symptoms": [{"text": "Increased thirst", "frequency": "common"}, {"text": "Frequent urination, including waking at night", "frequency": "common"}, {"text": "Tiredness or low energy", "frequency": "common"}, {"text": "Blurred vision that comes and goes", "frequency": "sometimes"}, {"text": "Numbness, tingling or burning in the feet", "frequency": "sometimes"}, {"text": "Increased hunger", "frequency": "sometimes"}, {"text": "Unintentional weight loss", "frequency": "sometimes"}, {"text": "Slow-healing cuts or sores", "frequency": "sometimes"}, {"text": "Recurrent yeast or urinary infections", "frequency": "sometimes"}, {"text": "Dry, itchy skin", "frequency": "sometimes"}, {"text": "Erectile dysfunction", "frequency": "sometimes"}], "pertinent_negatives": ["Vomiting and deep rapid breathing (as in diabetic ketoacidosis)", "Sudden severe weight loss over weeks", "Chest pain or pressure", "One-sided weakness, numbness or trouble speaking", "Severe abdominal pain", "Fruity or acetone breath", "Symptoms that began over days rather than months"]}, "ros": [{"system": "constitutional", "positives": [{"text": "Tiredness", "frequency": "common"}, {"text": "Unintentional weight loss", "frequency": "sometimes"}], "negatives": ["Fever", "Night sweats", "Rapid weight loss over weeks"]}, {"system": "eyes", "positives": [{"text": "Blurry vision that fluctuates", "frequency": "sometimes"}], "negatives": ["Sudden vision loss", "Eye pain", "Flashes or floaters"], "argues_against": ["Retinal detachment", "Acute angle-closure glaucoma"]}, {"system": "gastrointestinal", "positives": [{"text": "Increased appetite", "frequency": "sometimes"}], "negatives": ["Vomiting", "Severe abdominal pain", "Blood in stool", "Jaundice"], "argues_against": ["Diabetic ketoacidosis", "Acute pancreatitis"]}, {"system": "genitourinary", "positives": [{"text": "Frequent urination, including at night", "frequency": "common"}, {"text": "Recurrent yeast infections", "frequency": "sometimes"}, {"text": "Erectile dysfunction", "frequency": "sometimes"}], "negatives": ["Burning with urination", "Blood in urine", "Flank pain", "Difficulty starting the stream"], "argues_against": ["Urinary tract infection", "Kidney stones", "Prostate obstruction"]}, {"system": "neurologic", "positives": [{"text": "Numbness or tingling in the feet", "frequency": "sometimes"}, {"text": "Burning pain in the feet at night", "frequency": "sometimes"}], "negatives": ["One-sided weakness", "Trouble speaking", "Sudden severe headache", "Loss of balance"], "argues_against": ["Stroke", "Acute neuropathy from another cause"]}, {"system": "skin", "positives": [{"text": "Dark velvety skin at the neck or armpits", "frequency": "sometimes"}, {"text": "Dry, itchy skin", "frequency": "sometimes"}, {"text": "Sores that heal slowly", "frequency": "sometimes"}], "negatives": ["Rash covering the body", "New blistering", "Skin ulcers with black edges"], "argues_against": ["Severe skin infection", "Necrotizing fasciitis"]}, {"system": "cardiovascular", "positives": [], "negatives": ["Chest pain", "Shortness of breath at rest", "Swelling in the legs", "Palpitations"], "argues_against": ["Acute coronary syndrome", "Heart failure"]}], "atypical": [{"population": "children", "how_it_differs": "Type 2 diabetes in children and teens usually comes with obesity and a strong family history; they may have no symptoms and be found on screening, or present with acanthosis nigricans and high blood pressure.", "missing_classic_features": ["Long slow onset over years", "Symptoms attributed to aging"]}, {"population": "older_adults", "how_it_differs": "Symptoms are often blamed on aging; thirst may be blunted, and they may present with confusion, falls, poor wound healing or a hyperglycemic emergency instead of classic thirst and urination.", "missing_classic_features": ["Marked thirst", "Increased appetite"]}, {"population": "pregnancy", "how_it_differs": "High blood sugar first found in pregnancy is usually gestational diabetes; it is often silent and picked up on routine screening, and it raises the risk of later type 2 diabetes.", "missing_classic_features": ["Classic thirst and urination symptoms"]}, {"population": "obesity", "how_it_differs": "Patients with obesity may have insulin resistance and acanthosis nigricans for years before glucose rises; symptoms stay mild and the diagnosis is often made on screening labs.", "missing_classic_features": ["Unintentional weight loss"]}]}, "exam": {"general": {"mild": "Well-appearing, often overweight or obese, no distress", "moderate": "Well-appearing but tired; may look overweight with central adiposity", "severe": "Ill-appearing, dehydrated, drowsy or confused", "critical": "Lethargic or obtunded, dry mucous membranes, deep rapid breathing, signs of shock"}, "findings": [{"id": "elevated-bmi", "region": "general", "maneuver": "Measure height and weight and calculate BMI; measure waist circumference", "finding": "BMI in the overweight or obese range with central adiposity", "frequency": "almost_always", "significance": "supports", "importance": "essential"}, {"id": "acanthosis-nigricans", "region": "skin", "maneuver": "Inspect the back of the neck, axillae and skin folds", "finding": "Dark, thick, velvety skin in flexural areas", "frequency": "sometimes", "significance": "supports", "importance": "important"}, {"id": "skin-tags", "region": "skin", "maneuver": "Inspect the neck and axillae", "finding": "Small skin tags", "frequency": "sometimes", "significance": "supports", "importance": "optional"}, {"id": "foot-ulcer", "region": "extremities", "maneuver": "Inspect the soles, between the toes and over pressure points of both feet", "finding": "Non-healing ulcer or callus, often at a pressure point", "frequency": "sometimes", "min_severity": 