insert into private.condition_profiles (slug, name, primary_clerkship, clerkships, organ_systems, validation, review, profile) values ($rounds_kb$e-coli-infections$rounds_kb$, $rounds_kb$E. coli Infections$rounds_kb$, $rounds_kb$internalMedicine$rounds_kb$, array[$rounds_kb$internalMedicine$rounds_kb$, $rounds_kb$pediatrics$rounds_kb$, $rounds_kb$emergency$rounds_kb$, $rounds_kb$familyMedicine$rounds_kb$]::text[], array[$rounds_kb$blood$rounds_kb$, $rounds_kb$renal$rounds_kb$, $rounds_kb$gastrointestinal$rounds_kb$]::text[], $rounds_kb$passed$rounds_kb$, $rounds_kb$pending$rounds_kb$, $rounds_kb${"schema_version": "0.2", "slug": "e-coli-infections", "triage": {"name": "E. coli Infections", "case_suitable": true, "reason": "A specific pathogen with distinct clinical syndromes (UTI, gastroenteritis, sepsis) that students diagnose via history, exam and cultures.", "kind": "disease", "category": "bacterial infection", "organ_systems": ["blood", "renal", "gastrointestinal"], "primary_clerkship": "internalMedicine", "secondary_clerkships": ["pediatrics", "emergency", "familyMedicine"], "commonness": "very_common", "settings": ["clinic", "inpatient", "emergency"], "is_cancer": false}, "generation": {"stages": [{"stage": "triage", "model": "deepseek/deepseek-chat", "prompt_version": "7", "generated_at": "2026-10-05T04:17:07Z"}, {"stage": "patient_presentation", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:08:32Z"}, {"stage": "exam_vitals", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:08:38Z"}, {"stage": "diagnostics", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:08:59Z"}, {"stage": "differential_course", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:09:08Z"}, {"stage": "teaching", "model": "deepseek/deepseek-chat", "prompt_version": "8", "generated_at": "2026-10-05T05:09:13Z"}], "validation": {"status"