, "risk_factors": [{"text": "Previous fainting episodes", "strength": "strong"}, {"text": "Prolonged standing, warm environments, or crowded rooms", "strength": "moderate"}, {"text": "Emotional stress, pain, or the sight of blood", "strength": "moderate"}, {"text": "Dehydration or missed meals", "strength": "moderate"}, {"text": "Straining, coughing, or urinating (situational triggers)", "strength": "weak"}, {"text": "Family history of fainting", "strength": "weak"}], "comorbidities": ["Heart disease, including arrhythmias, valve disease, or heart failure", "Diabetes", "Parkinson disease or other conditions causing autonomic dysfunction", "Anemia", "Pregnancy"], "family_history": ["Fainting or sudden cardiac death in a close relative"], "social_history": ["Athletic training or military drill with prolonged standing", "Hot weather or outdoor work"], "exposures": ["Warm, crowded environments", "Prolonged motionless standing"], "risk_medications": ["hydrochlorothiazide", "furosemide", "lisinopril", "metoprolol", "doxazosin", "nitroglycerin", "sertraline", "insulin"]}, "presentation": {"chief_complaints": [{"text": "I passed out", "frequency": "almost_always"}, {"text": "I felt like I was going to faint", "frequency": "common"}, {"text": "I blacked out for a few seconds", "frequency": "common"}], "hpi": {"onset": "Sudden, often while standing or shortly after standing up", "duration": "Loss of consciousness lasts seconds to about a minute; full recovery within minutes", "progression": "A warning feeling of lightheadedness, warmth, or nausea builds over seconds, then consciousness is lost and the person slumps or falls; recovery is quick and complete", "location": "Whole-body event; no focal location", "radiation": "Not applicable", "quality": "Brief loss of consciousness with loss of muscle tone", "severity": "Episodes are brief but can cause injury from falling", "timing": "Occurs while standing or sitting upright; not during sleep", "aggravating": ["Standing for a long time", "Warm or crowded rooms", "Pain or the sight of blood", "Emotional stress", "Standing up quickly", "Straining or coughing"], "relieving": ["Lying down", "Sitting with the head lowered", "Cool air and fluids"], "associated_symptoms": [{"text": "Lightheadedness or dizziness before the event", "frequency": "common"}, {"text": "Nausea", "frequency": "common"}, {"text": "Cold, clammy skin and sweating", "frequency": "common"}, {"text": "Blurred, dimming, or tunnel vision", "frequency": "common"}, {"text": "Ringing in the ears", "frequency": "sometimes"}, {"text": "Brief jerking movements of the arms or legs during the faint", "frequency": "sometimes"}, {"text": "Feeling tired or confused for a short time afterward", "frequency": "sometimes"}], "pertinent_negatives": ["Chest pain or palpitations before the event", "Loss of consciousness during exercise or while lying down", "Confusion lasting more than a few minutes after waking", "Tongue biting", "Loss of bladder or bowel control", "Fever", "One-sided weakness or numbness", "Severe headache", "Recent head injury"]}, "ros": [{"system": "cardiovascular", "positives": [{"text": "Palpitations just before fainting", "frequency": "sometimes"}, {"text": "Feeling of the heart racing", "frequency": "sometimes"}], "negatives": ["Chest pain", "Fainting during exertion", "Leg swelling"], "argues_against": ["Fainting during exercise suggests a heart rhythm or structural heart cause"]}, {"system": "neurologic", "positives": [{"text": "Lightheadedness before the event", "frequency": "common"}, {"text": "Brief jerking movements during the faint", "frequency": "sometimes"}], "negatives": ["Persistent confusion", "Weakness on one side", "Trouble speaking", "Severe headache", "Vision loss in one eye"], "argues_against": ["Prolonged confusion after the event", "Focal neurologic deficits"]}, {"system": "gastrointestinal", "positives": [{"text": "Nausea", "frequency": "common"}], "negatives": ["Vomiting blood", "Black stools", "Severe abdominal pain"], "argues_against": ["Bleeding causing low blood volume"]}, {"system": "constitutional", "positives": [{"text": "Feeling warm or sweaty before the event", "frequency": "common"}], "negatives": ["Fever", "Weight loss", "Night sweats"]}, {"system": "psychiatric", "positives": [{"text": "Anxiety or emotional stress before the event", "frequency": "sometimes"}], "negatives": ["Symptoms occurring only when observed by others", "Intentional self-injury"]}], "atypical": [{"population": "older_adults", "how_it_differs": "Fainting is more often caused by heart rhythm problems, medication effects, or orthostatic drops in blood pressure; warning symptoms may be absent and injuries from falls are more common.", "missing_classic_features": ["Clear warning before the event", "Obvious trigger such as heat or emotion"]}, {"population": "children", "how_it_differs": "Young children may not describe warning symptoms and instead appear pale, limp, or briefly unresponsive, often after a fall, pain, or crying.", "missing_classic_features": ["Ability to describe lightheadedness or vision changes"]}, {"population": "pregnancy", "how_it_differs": "Fainting can occur from pressure of the uterus on the large veins when lying flat, from low blood sugar, or from anemia; it is more likely in later pregnancy.", "missing_classic_features": ["Fainting only while standing"]}]}, "exam": {"general": {"mild": "Alert, fully oriented, no distress; normal between episodes", "moderate": "Pale and diaphoretic, looks unwell but fully alert and oriented", "severe": "Pale, clammy, anxious; may have injured themselves in the fall", "critical": "Altered mental status or persistent unresponsiveness; may have obvious trauma"}, "findings": [{"id": "orthostatic-vitals", "region": "general", "maneuver": "Measure blood pressure and heart rate supine, then after standing for 1 and 3 minutes", "finding": "Drop in systolic blood pressure of at least 20 mm Hg or diastolic of at least 10 mm Hg within 3 mi